            ['id' => 12, 'title' => 'SQL: gezielt suchen mit WHERE', 'description' => 'Öffne den Shop in der SQL-Werkstatt und schreibe Abfragen: alle Produkte über 50 Euro, alle Produkte eines Herstellers deiner Wahl, sortiert nach Preis absteigend. Erkläre die Reihenfolge der Schlüsselwörter in einer SELECT-Anweisung.', 'type' => 'sql', 'level' => 9],
            ['id' => 13, 'title' => 'SQL: Tabellen verbinden mit JOIN', 'description' => 'Verbinde in der Shop-Datenbank die Tabelle produkte mit der Tabelle der Hersteller: Gib Produktname, Hersteller und Preis gemeinsam aus. Erweitere die Abfrage so, dass nur Produkte unter 20 Euro erscheinen.', 'type' => 'sql', 'level' => 10],
            ['id' => 14, 'title' => 'Erste eigene Java-Klasse', 'description' => 'Lege in der Code-Werkstatt eine Klasse Auto an: Attribute für Farbe und Geschwindigkeit, ein Konstruktor, eine Methode beschleunigen und eine Methode, die den Status mit System.out.println ausgibt. Teste alles in der main-Methode.', 'type' => 'code', 'level' => 9],
            ['id' => 25, 'title' => 'Funktionale Modellierung: Getränkeautomat als Datenfluss', 'description' => 'Modelliere einen Getränkeautomaten als verkettete Funktionen: Nenne drei Funktionen mit jeweils Eingabe und Ausgabe, zeichne das Datenflussdiagramm in dein Heft und ergänze eine Prüffunktion, die zu wenig eingeworfenes Geld erkennt. Vergleiche danach mit der Präsentation *Funktionale Modellierung*.', 'type' => 'allgemein', 'level' => 9],
            ['id' => 26, 'title' => 'Tabellenkalkulation: absolute Bezüge richtig setzen', 'description' => 'Gegeben ist eine Artikelliste mit Nettopreisen (Spalte B); in F1 steht fest der Mehrwertsteuersatz 19%. Schreibe die Formeln für den Bruttopreis (kopierbar, absoluter Bezug auf F1), eine Rundung auf zwei Nachkommastellen und eine WENN-Formel, die unter 5 Euro "geschenkt" ausgibt. Erkläre, warum der Bezug absolut sein muss.', 'type' => 'allgemein', 'level' => 9],
            ['id' => 27, 'title' => 'Datenschutz: Deine Daten in der Schule', 'description' => 'Liste alle personenbezogenen Daten, die deine Schule über dich speichert. Markiere für jeden Eintrag, wer zugreifen darf (du, Lehrkräfte, Verwaltung, Mitschülerinnen und Mitschüler). Finde je ein Beispiel für Datensparsamkeit und eine Situation, in der du Auskunft verlangen könntest, und erkläre den Begriff Data-Mining an einem Beispiel.', 'type' => 'allgemein', 'level' => 9],
            ['id' => 28, 'title' => 'Java: if-else mit Struktogramm (Führerschein-Check)', 'description' => 'Zeichne zuerst ein Struktogramm für die Methode darfFuehren(alterStart): ab 18 "Darf Auto fahren!", genau 17 "Nur mit Begleitung.", darunter "Noch warten ...". Schreibe danach die Methode in der Code-Werkstatt und teste sie mit 18, 17 und 15. Erkläre, warum hier else if besser passt als zwei einzelne if-Anweisungen.', 'type' => 'code', 'level' => 9],
            // Jahrgangsstufe 10: Vertiefung
            ['id' => 16, 'title' => 'SQL: Auswertungen mit GROUP BY', 'description' => 'Bilde in der Shop-Datenbank je Hersteller die Anzahl der Produkte und den Durchschnittspreis. Sortiere nach Durchschnittspreis absteigend und erkläre den Unterschied zwischen WHERE und HAVING.', 'type' => 'sql', 'level' => 10, 'todos' => ['SELECT mit GROUP BY ueben: Anzahl der Produkte je Hersteller', 'Durchschnittspreis mit AVG ergaenzen', 'Ergebnis mit ORDER BY sortieren', 'WHERE und HAVING in zwei Saetzen erklaeren'], 'solution' => "SELECT h.name AS hersteller, COUNT(*) AS anzahl, AVG(p.preis) AS durchschnitt\nFROM produkte p\nJOIN hersteller h ON p.hersteller_id = h.id\nGROUP BY h.name\nORDER BY durchschnitt DESC;\n\nWHERE filtert einzelne Zeilen VOR der Gruppierung, HAVING filtert ganze Gruppen NACH der Gruppierung (z. B. HAVING COUNT(*) > 2)."],
            ['id' => 17, 'title' => 'Java: Vererbung am Beispiel Tiere', 'description' => 'Baue eine Klasse Tier mit privaten Attributen und einer public-Methode gibLaut(). Erzeuge davon die Klassen Hund und Katze, ueberschreibe gibLaut() und teste mit einem Tier-Array: In der Schleife entscheidet die dynamische Bindung, welche Laut-Methode wirklich laeuft.', 'type' => 'code', 'level' => 10, 'todos' => ['Klasse Tier mit privatem Attribut name und public gibLaut() anlegen', 'Zugriffsmethode gibNamen() in Tier ergaenzen (Attribut ist privat)', 'Klasse Hund mit extends Tier und @Override anlegen', 'Klasse Katze mit extends Tier und @Override anlegen', 'Tier-Array am Dateiende fuellen und gibLaut() in einer Schleife aufrufen', 'Beobachten und erklaeren: Welche Methode laeuft wirklich?'], 'solution' => "public class Tier {\n    private String name;\n\n    public Tier(String nameStart) {\n        name = nameStart;\n    }\n\n    public String gibNamen() {\n        return name;\n    }\n\n    public void gibLaut() {\n        System.out.println(gibNamen() + \" macht ein Geraeusch.\");\n    }\n}\n\npublic class Hund extends Tier {\n    public Hund(String nameStart) {\n        super(nameStart);\n    }\n\n    @Override\n    public void gibLaut() {\n        System.out.println(gibNamen() + \" sagt: Wuff!\");\n    }\n}\n\npublic class Katze extends Tier {\n    public Katze(String nameStart) {\n        super(nameStart);\n    }\n\n    @Override\n    public void gibLaut() {\n        System.out.println(gibNamen() + \" sagt: Miau!\");\n    }\n}\n\nTier[] gehege = { new Hund(\"Rex\"), new Katze(\"Mimi\"), new Tier(\"Unbekannt\") };\nfor (int i = 0; i < gehege.length; i++) {\n    gehege[i].gibLaut();\n}", 'files' => [['name' => 'TiereStarter.java', 'content' => "// Vorlage: Ergaenze die Klassen und teste mit dem Tier-Array am Dateiende.\npublic class Tier {\n    private String name;\n\n    public Tier(String nameStart) {\n        name = nameStart;\n    }\n\n    public String gibNamen() {\n        return name;\n    }\n\n    public void gibLaut() {\n        // Hier lautgeben\n    }\n}\n\n// 1) Klasse Hund mit extends Tier anlegen und gibLaut() ueberschreiben\n// 2) Klasse Katze genauso\n\n// 3) Testen am Dateiende:\n// Tier[] gehege = { new Hund(\"Rex\"), new Katze(\"Mimi\") };\n// for (int i = 0; i < gehege.length; i++) { gehege[i].gibLaut(); }"]]],
            ['id' => 18, 'title' => 'ER-Modell für eine Schulverwaltung', 'description' => 'Entwirf für eine kleine Notenverwaltung ein ER-Modell: Schueler, Kurse und Noten mit Beziehungen und Kardinalitäten (z. B. m:n mit Zwischentabelle). Markiere Primär- und Fremdschlüssel.', 'type' => 'sql', 'level' => 10, 'todos' => ['Entitaeten Schueler, Kurs und Noten identifizieren', 'Kardinalitaeten notieren (wer gehoert zu wem?)', 'Zwischentabelle fuer die m:n-Beziehung entwerfen', 'Primar- und Fremdschluessel markieren', 'CREATE TABLE in der SQL-Werkstatt ausprobieren (Vorlage notenverwaltung.sql)'], 'solution' => "Beziehungen: Schueler (1) -- (n) Belegung -- (n) Kurs. Die Noten liegen in der Zwischentabelle belegung (m:n mit Attribut).\n\nCREATE TABLE schueler (\n    id INTEGER PRIMARY KEY,\n    name TEXT\n);\n\nCREATE TABLE kurs (\n    id INTEGER PRIMARY KEY,\n    name TEXT\n);\n\nCREATE TABLE belegung (\n    schueler_id INTEGER REFERENCES schueler(id),\n    kurs_id INTEGER REFERENCES kurs(id),\n    note REAL,\n    PRIMARY KEY (schueler_id, kurs_id)\n);\n\nINSERT INTO schueler (id, name) VALUES (1, 'Lena');\nINSERT INTO kurs (id, name) VALUES (1, 'Informatik');\nINSERT INTO belegung (schueler_id, kurs_id, note) VALUES (1, 1, 2.0);\n\nSELECT s.name, k.name, b.note FROM belegung b\nJOIN schueler s ON b.schueler_id = s.id\nJOIN kurs k ON b.kurs_id = k.id;", 'files' => [['name' => 'notenverwaltung.sql', 'content' => "-- Beispieldatenbank: kleine Notenverwaltung\n-- Fuehre die Anweisungen in der SQL-Werkstatt aus und ergaenze eigene Daten.\n\nCREATE TABLE schueler (\n    id INTEGER PRIMARY KEY,\n    name TEXT,\n    klasse TEXT\n);\n\nCREATE TABLE kurs (\n    id INTEGER PRIMARY KEY,\n    name TEXT,\n    lehrkraft TEXT\n);\n\nCREATE TABLE belegung (\n    schueler_id INTEGER REFERENCES schueler(id),\n    kurs_id INTEGER REFERENCES kurs(id),\n    note REAL,\n    PRIMARY KEY (schueler_id, kurs_id)\n);\n\nINSERT INTO schueler (id, name, klasse) VALUES (1, 'Lena', '10G');\nINSERT INTO schueler (id, name, klasse) VALUES (2, 'Jonas', '10G');\nINSERT INTO schueler (id, name, klasse) VALUES (3, 'Emma', '10G');\n\nINSERT INTO kurs (id, name, lehrkraft) VALUES (1, 'Informatik', 'Herr Schmidt');\nINSERT INTO kurs (id, name, lehrkraft) VALUES (2, 'Mathematik', 'Frau Fischer');\n\nINSERT INTO belegung (schueler_id, kurs_id, note) VALUES (1, 1, 1.7);\nINSERT INTO belegung (schueler_id, kurs_id, note) VALUES (1, 2, 2.3);\nINSERT INTO belegung (schueler_id, kurs_id, note) VALUES (2, 1, 2.0);\nINSERT INTO belegung (schueler_id, kurs_id, note) VALUES (3, 2, 1.3);"]]],
            ['id' => 29, 'title' => 'Java: Datenkapselung mit private', 'description' => 'Baue die Klasse Schueler mit privaten Attributen name (String) und note (double): public-Konstruktor mit ...Start-Parametern, public getName(), setName(String nameNeu) und setNote(double noteNeu), der Noten ausserhalb von 1 bis 6 ablehnt. Teste am Dateiende mit setNote(99): Die Note darf sich nicht aendern. Erklaere den Vorteil der Kapselung in zwei Saetzen.', 'type' => 'code', 'level' => 10, 'todos' => ['Klasse Schueler mit privaten Attributen anlegen', 'Public-Konstruktor mit nameStart und noteStart schreiben', 'Public-Getter getName() ergaenzen', 'Public-Setter setNote() mit Pruefung 1 bis 6 schreiben', 'Testen am Dateiende: setNote(99) muss abgelehnt werden', 'Vorteil der Kapselung in zwei Saetzen erklaeren'], 'solution' => "public class Schueler {\n    private String name;\n    private double note;\n\n    public Schueler(String nameStart, double noteStart) {\n        name = nameStart;\n        note = noteStart;\n    }\n\n    public String getName() {\n        return name;\n    }\n\n    public void setName(String nameNeu) {\n        name = nameNeu;\n    }\n\n    public void setNote(double noteNeu) {\n        if (noteNeu >= 1 && noteNeu <= 6) {\n            note = noteNeu;\n        } else {\n            System.out.println(\"Ungueltige Note: \" + noteNeu);\n        }\n    }\n\n    public void zeigen() {\n        System.out.println(getName() + \" hat die Note \" + note);\n    }\n}\n\nSchueler lena = new Schueler(\"Lena\", 1.7);\nlena.setNote(99);\nlena.zeigen();\n\n// Vorteil: Das Objekt schuetzt seine eigenen Daten. Ungueltige Werte kommen\n// gar nicht erst hinein, und die Pruefregel steht an genau einer Stelle.", 'files' => [['name' => 'SchuelerStarter.java', 'content' => "// Vorlage: Klassen und Methoden public setzen, Attribute privat halten.\npublic class Schueler {\n    private String name;\n    private double note;\n\n    public Schueler(String nameStart, double noteStart) {\n        name = nameStart;\n        note = noteStart;\n    }\n\n    // 1) getName() ergaenzen\n    // 2) setNote(double noteNeu) mit Pruefung schreiben\n    // 3) Testen am Dateiende: new Schueler(\"Lena\", 1.7) und setNote(99)"]]],
            ['id' => 30, 'title' => 'Java: Arrays und Referenzen', 'description' => 'Gegeben: int[] zeiten = {312, 287, 305, 298}. Schreibe eine Methode besteZeit(int[] zeitenStart), die die kleinste Zeit zurückgibt, und drucke zusätzlich den Index. Erkläre danach, warum int[] b = a; dazu führt, dass Änderungen über b auch in a sichtbar sind.', 'type' => 'code', 'level' => 10, 'todos' => ['Methode besteZeit() mit Rueckgabe schreiben', 'Index der besten Zeit mit ausgeben', 'Testen mit dem Array {312, 287, 305, 298}', 'Referenz-Experiment: int[] b = a und b[0] aendern', 'Beobachten und erklaeren: Was passiert mit a?'], 'solution' => "int[] zeiten = {312, 287, 305, 298};\n\nint besteZeit(int[] zeitenStart) {\n    int beste = zeitenStart[0];\n    int index = 0;\n    for (int i = 1; i < zeitenStart.length; i++) {\n        if (zeitenStart[i] < beste) {\n            beste = zeitenStart[i];\n            index = i;\n        }\n    }\n    System.out.println(\"Beste Zeit: \" + beste + \" (Index \" + index + \")\");\n    return beste;\n}\n\nbesteZeit(zeiten);\n\nint[] b = zeiten;\nb[0] = 999;\nSystem.out.println(zeiten[0]); // druckt 999!\n\nErklarung: Arrays sind Referenztypen. b = zeiten kopiert nicht die Werte, sondern die Adresse. Beide Variablen zeigen auf dasselbe Array im Speicher.", 'files' => [['name' => 'ZeitenStarter.java', 'content' => "// Vorlage: Ergaenze die Methode und das Referenz-Experiment.\nint[] zeiten = {312, 287, 305, 298};\n\n// 1) Methode besteZeit(int[] zeitenStart) schreiben\n// 2) Index der besten Zeit mit ausgeben\n// 3) Aufrufen und testen\n\n// 4) Referenz-Experiment:\n// int[] b = zeiten;\n// b[0] = 999;\n// System.out.println(zeiten[0]);"]]],
            ['id' => 31, 'title' => 'Projekt: Planung und Dokumentation', 'description' => 'Einigt euch auf eine Projektidee (Java-Programm oder Datenbankanwendung) und schreibt einen Projektplan: Ziel, Teamrollen, vier Meilensteine mit Terminen und eine grobe Modellierung (Klassen bzw. Tabellen als Skizze). Legt fest, wann ihr testet und was dabei geprüft wird. Die Vorstellung des Plans dauert 2 Minuten.', 'type' => 'allgemein', 'level' => 10, 'todos' => ['Projektidee im Team festlegen und in einem Satz formulieren', 'Teamrollen verteilen (Modellierung, Umsetzung, Test, Dokumentation)', 'Vier Meilensteine mit Terminen ins Projektplan-Dokument schreiben', 'Grobe Modellierung skizzieren (Klassen oder Tabellen)', 'Testplan festlegen: Was wird wann geprueft?', 'Abgabe des Plans als Text oder Foto der Skizze'], 'solution' => "Muster-Projektplan (Beispiel Freizeitbad-Verwaltung):\n\nZiel: Ein Java-Programm verwaltet Eintrittskarten und Besucher einer Freizeitbad-Anlage.\n\nTeamrollen: Maya - Modellierung, Jonas - Umsetzung Klassen, Lena - Umsetzung Datenbank, Tim - Test und Dokumentation.\n\nMeilensteine:\n1. Woche 1: Klassendiagramm steht (Besucher, Karte, Bad).\n2. Woche 2: Klassen mit Konstruktor und Kapselung laufen.\n3. Woche 3: Datenbank-Anbindung, Karten liegen in einer Tabelle.\n4. Woche 4: Testphase und Praesentation.\n\nTestplan: Jede Methode wird mit gueltigen und ungueltigen Werten getestet (z. B. negative Preise); die Praesentation uebt das Team einmal komplett."],
            ['id' => 32, 'title' => 'SQL: JOIN mit Bedingungen', 'description' => 'Öffne die Shop-Datenbank: Zeige zu jeder Bestellung den Vor- und Nachnamen des Kunden und das Datum (JOIN über kunde_id), danach zu jeder Bestellposition das Produkt und die Menge (JOIN über produkt_id). Schränke eine der Abfragen mit WHERE ein und berechne als Bonus den Gesamtwert aller Bestellungen mit SUM.', 'type' => 'sql', 'level' => 10, 'todos' => ['JOIN Bestellung mit Kunde ueber kunde_id schreiben', 'JOIN Bestellposition mit Produkt ueber produkt_id schreiben', 'Eine Abfrage mit WHERE einschraenken', 'Bonus: Gesamtwert aller Bestellungen mit SUM(menge * preis) berechnen'], 'solution' => "-- Bestellungen mit Kundendaten\nSELECT b.id, k.vorname, k.nachname, b.datum\nFROM bestellungen b\nJOIN kunden k ON b.kunde_id = k.id;\n\n-- Bestellpositionen mit Produkt und Menge\nSELECT bp.bestellung_id, p.name AS produkt, bp.menge\nFROM bestellpositionen bp\nJOIN produkte p ON bp.produkt_id = p.id\nWHERE bp.menge > 1;\n\n-- Bonus: Gesamtwert aller Bestellungen\nSELECT SUM(bp.menge * p.preis) AS gesamt\nFROM bestellpositionen bp\nJOIN produkte p ON bp.produkt_id = p.id;"],
            ['id' => 33, 'title' => 'SQL: Daten gezielt ändern mit UPDATE und DELETE', 'description' => 'In der Shop-Datenbank sind Preise gestiegen: Erhöhe alle Produkte über 100 Euro um 5 Prozent (UPDATE mit WHERE und berechneter Spalte). Lösche danach alle Bestellungen, die älter als ein selbst gewähltes Datum sind. Erkläre, warum ein UPDATE ohne WHERE gefährlich ist.', 'type' => 'sql', 'level' => 10, 'todos' => ['SELECT testen: Welche Produkte liegen ueber 100 Euro?', 'UPDATE mit WHERE und preis * 1.05 schreiben', 'Kontrollieren, dass nur die passenden Zeilen geaendert wurden', 'DELETE mit Datum-Bedingung schreiben', 'In zwei Saetzen erklaeren: Warum ist UPDATE ohne WHERE gefaehrlich?'], 'solution' => "-- Erst schauen, dann aendern\nSELECT name, preis FROM produkte WHERE preis > 100;\n\n-- Preise ueber 100 Euro um 5 Prozent erhoehen\nUPDATE produkte SET preis = preis * 1.05 WHERE preis > 100;\n\n-- Alte Bestellungen loeschen\nDELETE FROM bestellungen WHERE datum < '2020-01-01';\n\nUPDATE ohne WHERE aendert JEDE Zeile der Tabelle - aus Versehen sind damit alle Preise der ganzen Datenbank ueberschrieben. Immer zuerst mit SELECT pruefen, welche Zeilen die WHERE-Bedingung trifft."],
            ['id' => 34, 'title' => 'Datenmodellierung: Bibliothek mit n:m-Beziehung', 'description' => 'Eine Bibliothek verwaltet Bücher, Mitglieder und Ausleihen. Ein Mitglied leiht viele Bücher aus, ein Buch wird von vielen Mitgliedern ausgeliehen (n:m mit Ausleihdatum in der Hilfstabelle). Entwirf das Tabellenschema mit Primär- und Fremdschlüsseln und schreibe anschließend die CREATE-TABLE-Anweisungen in der SQL-Werkstatt.', 'type' => 'sql', 'level' => 10, 'todos' => ['Entitaeten buch und mitglied als Tabellen anlegen (Vorlage bibliothek.sql)', 'Hilfstabelle ausleihe mit beiden Fremdschluesseln entwerfen', 'Ausleihdatum als Attribut der Hilfstabelle begruenden', 'CREATE TABLE-Anweisungen in der SQL-Werkstatt ausfuehren', 'Test-JOIN schreiben: Wer hat welches Buch ausgeliehen?'], 'solution' => "CREATE TABLE buch (\n    id INTEGER PRIMARY KEY,\n    titel TEXT,\n    autor TEXT\n);\n\nCREATE TABLE mitglied (\n    id INTEGER PRIMARY KEY,\n    name TEXT\n);\n\nCREATE TABLE ausleihe (\n    buch_id INTEGER REFERENCES buch(id),\n    mitglied_id INTEGER REFERENCES mitglied(id),\n    ausleihdatum TEXT,\n    PRIMARY KEY (buch_id, mitglied_id)\n);\n\nINSERT INTO buch (id, titel, autor) VALUES (1, 'Java lernen', 'Ada Lovelace');\nINSERT INTO mitglied (id, name) VALUES (1, 'Lena');\nINSERT INTO ausleihe (buch_id, mitglied_id, ausleihdatum) VALUES (1, 1, '2026-11-08');\n\nSELECT m.name, b.titel, a.ausleihdatum\nFROM ausleihe a\nJOIN mitglied m ON a.mitglied_id = m.id\nJOIN buch b ON a.buch_id = b.id;\n\nDas Ausleihdatum gehoert zur Ausleihe: Es ist eine Eigenschaft der Beziehung zwischen Buch und Mitglied, nicht des Buches und nicht des Mitglieds.", 'files' => [['name' => 'bibliothek.sql', 'content' => "-- Beispieldatenbank: Bibliothek mit n:m-Beziehung\n-- Ergaenze die Hilfstabelle ausleihe und fuehre alles in der SQL-Werkstatt aus.\n\nCREATE TABLE buch (\n    id INTEGER PRIMARY KEY,\n    titel TEXT,\n    autor TEXT\n);\n\nCREATE TABLE mitglied (\n    id INTEGER PRIMARY KEY,\n    name TEXT\n);\n\nINSERT INTO buch (id, titel, autor) VALUES (1, 'Java lernen', 'Ada Lovelace');\nINSERT INTO buch (id, titel, autor) VALUES (2, 'SQL fuer Einsteiger', 'Grace Hopper');\nINSERT INTO buch (id, titel, autor) VALUES (3, 'Algorithmen kompakt', 'Alan Turing');\n\nINSERT INTO mitglied (id, name) VALUES (1, 'Lena');\nINSERT INTO mitglied (id, name) VALUES (2, 'Jonas');\nINSERT INTO mitglied (id, name) VALUES (3, 'Emma');\n\n-- 1) Hilfstabelle ausleihe anlegen (buch_id, mitglied_id, ausleihdatum)\n-- 2) Mindestens drei Ausleihen einfuegen\n-- 3) JOIN schreiben: Wer hat welches Buch wann ausgeliehen?"]]],
            ['id' => 35, 'title' => 'SQL: JOIN über drei Tabellen', 'description' => 'Verbinde in der Shop-Datenbank Bestellungen, Kunden und Produkte in EINER Abfrage: Zeige Vor- und Nachname des Kunden, den Produktnamen und die Menge je Bestellposition. Sortiere nach Nachname. Erkläre deinem Nachbarn, warum hier zwei JOINs nötig sind.', 'type' => 'sql', 'level' => 10, 'todos' => ['Erst mit zwei Tabellen starten: Bestellposition mit Produkt joinen', 'Zweiten JOIN auf kunden ergaenzen', 'Spalten klauen: Vorname, Nachname, Produkt, Menge', 'Mit ORDER BY nach Nachname sortieren', 'Dem Nachbarn erklaeren: Warum zwei JOINs?'], 'solution' => "SELECT k.vorname, k.nachname, p.name AS produkt, bp.menge\nFROM bestellpositionen bp\nJOIN produkte p ON bp.produkt_id = p.id\nJOIN bestellungen b ON bp.bestellung_id = b.id\nJOIN kunden k ON b.kunde_id = k.id\nORDER BY k.nachname;\n\nZwei JOINs sind noetig, weil Bestellpositionen nur produk_id und bestellung_id kennen. Der Kunde haengt indirekt ueber die Bestellung dran - erst der JOIN ueber zwei Zwischenschritte verbindet Position mit Kunde."],
            ['id' => 36, 'title' => 'Java: Fahrradverleih - Flotte als Array verwalten', 'description' => 'Baue die Klasse Fahrradverleih: ein privates Array der Laenge 5 fuer Fahrraeder, eine public-Methode vermieten(String farbe), die das naechste freie Fach belegt, und eine public-Methode zurueckgeben(int index). Erweitere um freiePlaetze(), das die Anzahl freier Faecher als int zurueckgibt. Teste am Dateiende mit drei Vermietungen und einer Rueckgabe.', 'type' => 'code', 'level' => 10, 'todos' => ['Klasse Fahrrad mit privatem Attribut farbe anlegen', 'Klasse Fahrradverleih mit privatem Array der Laenge 5 anlegen', 'Methode vermieten(String farbe) schreiben', 'Methode zurueckgeben(int index) schreiben', 'Methode freiePlaetze() mit Rueckgabe schreiben', 'Testen am Dateiende: drei Vermietungen, eine Rueckgabe, dann freiePlaetze()'], 'solution' => "public class Fahrrad {\n    private String farbe;\n\n    public Fahrrad(String farbeStart) {\n        farbe = farbeStart;\n    }\n\n    public String gibFarbe() {\n        return farbe;\n    }\n}\n\npublic class Fahrradverleih {\n    private Fahrrad[] felder = new Fahrrad[5];\n\n    public void vermieten(String farbe) {\n        for (int i = 0; i < felder.length; i++) {\n            if (felder[i] == null) {\n                felder[i] = new Fahrrad(farbe);\n                System.out.println(\"Fahrrad in Fach \" + i + \" vermietet.\");\n                return;\n            }\n        }\n        System.out.println(\"Kein freies Fach mehr!\");\n    }\n\n    public void zurueckgeben(int index) {\n        if (index >= 0 && index < felder.length && felder[index] != null) {\n            felder[index] = null;\n            System.out.println(\"Fach \" + index + \" ist wieder frei.\");\n        }\n    }\n\n    public int freiePlaetze() {\n        int frei = 0;\n        for (int i = 0; i < felder.length; i++) {\n            if (felder[i] == null) {\n                frei++;\n            }\n        }\n        return frei;\n    }\n}\n\nFahrradverleih leih = new Fahrradverleih();\nleih.vermieten(\"rot\");\nleih.vermieten(\"blau\");\nleih.vermieten(\"gruen\");\nleih.zurueckgeben(1);\nSystem.out.println(\"Freie Plaetze: \" + leih.freiePlaetze());", 'files' => [['name' => 'FahrradverleihStarter.java', 'content' => "// Vorlage: Ergaenze die Klasse Fahrradverleih.\npublic class Fahrrad {\n    private String farbe;\n\n    public Fahrrad(String farbeStart) {\n        farbe = farbeStart;\n    }\n}\n\n// 1) Klasse Fahrradverleih mit privatem Fahrrad[] felder = new Fahrrad[5]\n// 2) vermieten(String farbe): erstes freies Fach (null) belegen\n// 3) zurueckgeben(int index): Fach wieder auf null setzen\n// 4) freiePlaetze(): Anzahl der null-Felder als int zurueckgeben\n// 5) Testen am Dateiende mit drei Vermietungen und einer Rueckgabe"]]],
            ['id' => 37, 'title' => 'Java: Spartenabhaengige Mitgliedsbeitraege mit Polymorphismus', 'description' => 'Der Verein berechnet den Beitrag je Sparte: Klasse Mitglied mit public-Methode beitrag() (Basic 30 Euro), Unterklassen TennisMitglied (45 Euro) und SchwimmMitglied (40 Euro), jeweils mit @Override. Lege am Dateiende ein Mitglied[] mit allen drei Typen an und berechne in einer Schleife die Gesamtbeitraege. Erklaere, warum die Schleife ohne if-Abfrage auskommt.', 'type' => 'code', 'level' => 10, 'todos' => ['Klasse Mitglied mit privatem name und public beitrag() (30) anlegen', 'TennisMitglied mit extends und @Override (45) anlegen', 'SchwimmMitglied mit extends und @Override (40) anlegen', 'Mitglied[] am Dateiende mit allen drei Typen fuellen', 'Gesamtbeitrag in einer Schleife summieren', 'Erklaeren: Warum braucht die Schleife kein if?'], 'solution' => "public class Mitglied {\n    private String name;\n\n    public Mitglied(String nameStart) {\n        name = nameStart;\n    }\n\n    public int beitrag() {\n        return 30;\n    }\n}\n\npublic class TennisMitglied extends Mitglied {\n    public TennisMitglied(String nameStart) {\n        super(nameStart);\n    }\n\n    @Override\n    public int beitrag() {\n        return 45;\n    }\n}\n\npublic class SchwimmMitglied extends Mitglied {\n    public SchwimmMitglied(String nameStart) {\n        super(nameStart);\n    }\n\n    @Override\n    public int beitrag() {\n        return 40;\n    }\n}\n\nMitglied[] vereine = {\n    new Mitglied(\"Anna\"),\n    new TennisMitglied(\"Ben\"),\n    new SchwimmMitglied(\"Cem\")\n};\n\nint gesamt = 0;\nfor (int i = 0; i < vereine.length; i++) {\n    gesamt += vereine[i].beitrag();\n}\nSystem.out.println(\"Gesamtbeitraege: \" + gesamt);\n\n// Ohne if: Java ruft zur Laufzeit die beitrag()-Methode der konkreten Klasse\n// des Objekts auf (dynamische Bindung).", 'files' => [['name' => 'VereinStarter.java', 'content' => "// Vorlage: Ergaenze die Unterklassen und die Summe.\npublic class Mitglied {\n    private String name;\n\n    public Mitglied(String nameStart) {\n        name = nameStart;\n    }\n\n    public int beitrag() {\n        return 30;\n    }\n}\n\n// 1) TennisMitglied mit extends Mitglied, beitrag() auf 45 ueberschreiben\n// 2) SchwimmMitglied genauso (40)\n// 3) Mitglied[] am Dateiende mit allen drei Typen anlegen\n// 4) Gesamtbeitrag in einer Schleife summieren (ohne if!)"]]],
            ['id' => 38, 'title' => 'Projekt: Buchungssystem - Modellierung und erster Sprint', 'description' => 'Plant ein Buchungssystem für einen Fahrradverleih: Zeichnet das Klassendiagramm (Fahrrad, EBike, Kunde, Buchung) mit Beziehungen und Kardinalitäten, teilt die Klassen im Team auf und implementiert je Person eine Klasse mit Konstruktor, Datenkapselung und einer sinnvollen Methode. Testet gemeinsam: Was passiert bei einer Buchung ohne freies Fahrrad?', 'type' => 'allgemein', 'level' => 10, 'todos' => ['Klassendiagramm zeichnen: Fahrrad, EBike, Kunde, Buchung', 'Beziehungen und Kardinalitaeten beschriften (1:n, Vererbung)', 'Klassen im Team aufteilen', 'Je Person eine Klasse implementieren: Konstruktor, private Attribute, eine Methode', 'Gemeinsam testen: Buchung ohne freies Fahrrad probieren', 'Ergebnis als Beschreibung oder Foto des Diagramms abgeben'], 'solution' => "Modellierung (Beispiel):\n\n- Fahrrad (privat: id, zustaend; Methoden: ist frei / vermieten)\n- EBike erweitert Fahrrad (privat: akkuKapazitaet)\n- Kunde (privat: name; Methode: buchen(Fahrrad f))\n- Buchung verbindet Kunde und Fahrrad mit Datum (1:n: ein Kunde viele Buchungen, ein Fahrrad viele Buchungen ueber die Zeit)\n\nVerhalten ohne freies Fahrrad: buchen() prueft den Zustand und gibt eine Rueckmeldung statt stillschweigend zu buchen - genau das wird im gemeinsamen Test geprueft: Das Programm darf nicht abstuerzen, sondern meldet \"kein Fahrrad frei\"."],
            ['id' => 39, 'title' => 'Java-Warm-up: Klasse Auto auffrischen (Start in die 10. Klasse)', 'description' => 'Start in die Jahrgangsstufe 10: Frische dein Java-Wissen aus der 9. Klasse auf. Lege die Klasse Auto mit privaten Attributen, public-Konstruktor und public-Methoden an, ergaenze eine if-else-Entscheidung und eine Schleife. Die Testanweisungen stehen direkt am Dateiende von Auto.java: Objekt anlegen, dreimal beschleunigen, Status ausgeben. Wer diese Aufgabe sicher schafft, ist fuer die Kurzarbeit geruestet.', 'type' => 'code', 'level' => 10, 'todos' => ['Klasse Auto mit privaten Attributen farbe und geschwindigkeit anlegen', 'Public-Konstruktor mit farbeStart und geschwindigkeitStart schreiben', 'Public-Methode beschleunigen() schreiben, die die Geschwindigkeit um 20 erhoeht', 'if-else: Warnung ausgeben, wenn die Geschwindigkeit ueber 130 liegt', 'for-Schleife am Dateiende: dreimal beschleunigen und danach den Status ausgeben', 'Vorlage Auto.java ergaenzen (Klasse und Testanweisungen)'], 'solution' => "public class Auto {\n\n    // Attribute\n    private String farbe;\n    private int geschwindigkeit;\n\n    // Konstruktor\n    public Auto(String farbeStart, int geschwindigkeitStart) {\n        farbe = farbeStart;\n        geschwindigkeit = geschwindigkeitStart;\n    }\n\n    // eigene Methode\n    public void beschleunigen() {\n        geschwindigkeit = geschwindigkeit + 20;\n        if (geschwindigkeit > 130) {\n            System.out.println(\"Warnung: zu schnell!\");\n        } else {\n            System.out.println(\"Tempo ok.\");\n        }\n    }\n\n    public void status() {\n        System.out.println(\"Das \" + farbe + \"e Auto faehrt \" + geschwindigkeit + \" km/h.\");\n    }\n}\n\n// Testanweisungen am Dateiende\nAuto auto = new Auto(\"rot\", 0);\nfor (int i = 1; i <= 3; i++) {\n    auto.beschleunigen();\n}\nauto.status();", 'files' => [['name' => 'Auto.java', 'content' => "// Vorlage: Klasse Auto auffrischen\n// Ergaenze die Klasse Auto und arbeite die ToDos ab.\n// Die Testanweisungen stehen am Dateiende.\n\npublic class Auto {\n\n    // Attribute (privat)\n\n    // Konstruktor (public)\n\n    // Methode beschleunigen() (public)\n\n    // Methode status() (public)\n}\n\n// 1) Auto-Objekt anlegen\n// 2) dreimal beschleunigen (for-Schleife)\n// 3) status() ausgeben"]]],
            ['id' => 40, 'title' => 'Redundanz und Anomalien: Warum Daten nur einmal gespeichert werden', 'description' => 'In einer fehlerhaften Tabelle steht der Klassenlehrer bei jedem Schüler erneut. Lege die Tabelle aus der Vorlage in der SQL-Werkstatt an, führe ein UPDATE nur bei einem Teil der Schüler aus und weise mit SELECT nach, was dann schiefgeht. Erkläre danach Update-, Insert- und Lösch-Anomalie und entwirf die saubere Lösung mit zwei Tabellen.', 'type' => 'sql', 'level' => 10, 'todos' => ['Fehlerhafte Tabelle anlegen (Vorlage redundanz.sql)', 'UPDATE: Klassenlehrer nur bei zwei von fünf Schülern ändern', 'Mit SELECT nachweisen, dass die Tabelle sich nun widerspricht (Update-Anomalie)', 'Insert-Anomalie erklären: Warum kann eine neue Klasse ohne Schüler nicht angelegt werden?', 'Lösch-Anomalie erklären: Was passiert, wenn der letzte Schüler gelöscht wird?', 'Sauberes Schema mit zwei Tabellen (schueler, klassen) aufschreiben'], 'solution' => "Update-Anomalie: Nach dem UPDATE steht bei den Schülern 1 und 2 \"Frau Weber\", bei 3 bis 5 noch \"Herr Maier\". Die Information Klassenlehrer liegt fünfmal vor und widerspricht sich.\n\nInsert-Anomalie: Eine neue Klasse mit Lehrkraft kann nicht angelegt werden, ohne dass mindestens ein Schüler existiert.\n\nLösch-Anomalie: Wird der letzte Schüler seiner Klasse gelöscht, verschwindet auch die Information, wer die Klasse leitet.\n\nSaubere Lösung (Information nur einmal speichern):\n\nCREATE TABLE klassen (\n    id INTEGER PRIMARY KEY,\n    name TEXT,\n    klassenlehrer TEXT\n);\n\nCREATE TABLE schueler (\n    id INTEGER PRIMARY KEY,\n    name TEXT,\n    klassen_id INTEGER REFERENCES klassen(id)\n);\n\nDer Klassenlehrer steht jetzt genau einmal je Klasse - ein UPDATE genügt, Widersprüche sind unmöglich.", 'files' => [['name' => 'redundanz.sql', 'content' => "-- Fehlerhafte Beispieldatenbank: Der Klassenlehrer steht bei jedem Schüler erneut.\n-- Führe das UPDATE aus und beobachte, was passiert, wenn eine Änderung vergessen wird.\n\nCREATE TABLE schueler (\n    id INTEGER PRIMARY KEY,\n    name TEXT,\n    klassenlehrer TEXT\n);\n\nINSERT INTO schueler (id, name, klassenlehrer) VALUES (1, 'Lena', 'Herr Maier');\nINSERT INTO schueler (id, name, klassenlehrer) VALUES (2, 'Jonas', 'Herr Maier');\nINSERT INTO schueler (id, name, klassenlehrer) VALUES (3, 'Emma', 'Herr Maier');\nINSERT INTO schueler (id, name, klassenlehrer) VALUES (4, 'Ben', 'Herr Maier');\nINSERT INTO schueler (id, name, klassenlehrer) VALUES (5, 'Sofia', 'Herr Maier');\n\n-- 1) Ändere den Klassenlehrer NUR bei den Schülern 1 und 2:\n--    UPDATE schueler SET klassenlehrer = 'Frau Weber' WHERE id IN (1, 2);\n-- 2) SELECT * FROM schueler;   -> Wo liegt das Problem?\n-- 3) Entwirf eine Lösung mit zwei Tabellen."]]],
            ['id' => 41, 'title' => 'Vom Klassendiagramm zur Tabelle: OO-Modell in ein relationales Schema überführen', 'description' => 'Gegeben ein Objektmodell mit drei Klassen: Schüler (name), Kurs (thema) und Lehrkraft (name). Jeder Kurs hat genau eine Lehrkraft (1:n), ein Schüler besucht viele Kurse und ein Kurs hat viele Schüler (n:m). Überführe das Modell in ein relationales Schema, begründe Primär- und Fremdschlüssel und prüfe am Ende mit einem JOIN.', 'type' => 'sql', 'level' => 10, 'todos' => ['Je Klasse eine Tabelle mit Primärschlüssel anlegen (Vorlage schulmodell.sql)', '1:n: Kurs bekommt Fremdschlüssel lehrkraft_id', 'n:m: Hilfstabelle teilnahme mit zwei Fremdschlüsseln entwerfen', 'Primär- und Fremdschlüssel für jede Tabelle begründen', 'Testdaten einfügen und mit einem JOIN prüfen'], 'solution' => "CREATE TABLE lehrkraft (\n    id INTEGER PRIMARY KEY,\n    name TEXT\n);\n\nCREATE TABLE kurs (\n    id INTEGER PRIMARY KEY,\n    thema TEXT,\n    lehrkraft_id INTEGER REFERENCES lehrkraft(id)\n);\n\nCREATE TABLE schueler (\n    id INTEGER PRIMARY KEY,\n    name TEXT\n);\n\nCREATE TABLE teilnahme (\n    schueler_id INTEGER REFERENCES schueler(id),\n    kurs_id INTEGER REFERENCES kurs(id),\n    PRIMARY KEY (schueler_id, kurs_id)\n);\n\nJOIN-Prüfung:\n\nSELECT s.name, k.thema\nFROM teilnahme t\nJOIN schueler s ON t.schueler_id = s.id\nJOIN kurs k ON t.kurs_id = k.id;\n\nBegründung: Der Primärschlüssel macht jede Zeile eindeutig. Das 1:n wird als Fremdschlüssel kurs.lehrkraft_id abgebildet. Das n:m braucht eine eigene Hilfstabelle, sonst müssten Schüler oder Kurse mehrfach (redundant) gespeichert werden.", 'files' => [['name' => 'schulmodell.sql', 'content' => "-- Vorlage: Vom OO-Modell zur Tabelle\n-- Klassen: Schueler (name), Kurs (thema), Lehrkraft (name)\n-- 1:n  : Kurs -> Lehrkraft (Fremdschluessel in kurs)\n-- n:m  : Schueler <-> Kurs (Hilfstabelle noetig!)\n\nCREATE TABLE lehrkraft (\n    id INTEGER PRIMARY KEY,\n    name TEXT\n);\n\n-- 1) Tabelle kurs ergaenzen: Fremdschluessel lehrkraft_id\nCREATE TABLE kurs (\n    id INTEGER PRIMARY KEY,\n    thema TEXT\n);\n\n-- 2) Tabelle schueler anlegen\n\n-- 3) Hilfstabelle teilnahme entwerfen (zwei Fremdschluessel,\n--    gemeinsamer Primaerschluessel) und Testdaten einfuegen"]]],
            ['id' => 42, 'title' => 'SQL im Online-Shop: Artikel, Kunden und Bestellungen auswerten', 'description' => 'Der Online-Shop speichert Artikel, Kunden, Bestellungen und die enthaltenen Positionen in vier verknüpften Tabellen. Beantworte die Fragen des Betreibers: Welche Artikel kosten über 50 Euro? Was hat welcher Kunde wann bestellt? Wie hoch ist der Umsatz je Kunde? Und wie setzt du eine offene Bestellung auf versendet?', 'type' => 'sql', 'level' => 10, 'todos' => ['Shop-Datenbank anlegen (Vorlage shop.sql) und alle vier Tabellen ansehen', 'Alle Artikel über 50 Euro ausgeben', 'JOIN: Bestellungen mit Kundennamen und Bestelldatum anzeigen', 'JOIN über drei Tabellen: Positionen mit Artikelnamen und Menge', 'GROUP BY: Umsatz je Kunde berechnen (SUM)', 'UPDATE: Status einer offenen Bestellung auf versendet setzen'], 'solution' => "SELECT * FROM artikel;\nSELECT name, preis FROM artikel WHERE preis > 50;\n\nSELECT k.name, b.datum\nFROM bestellungen b\nJOIN kunden k ON b.kunden_id = k.id;\n\nSELECT bp.bestellung_id, a.name, bp.menge\nFROM bestellpositionen bp\nJOIN artikel a ON bp.artikel_id = a.id;\n\nSELECT k.name, SUM(a.preis * bp.menge) AS umsatz\nFROM bestellpositionen bp\nJOIN bestellungen b ON bp.bestellung_id = b.id\nJOIN kunden k ON b.kunden_id = k.id\nJOIN artikel a ON bp.artikel_id = a.id\nGROUP BY k.name;\n\nUPDATE bestellungen SET status = 'versendet' WHERE id = 1;", 'files' => [['name' => 'shop.sql', 'content' => "-- Beispieldatenbank: Online-Shop\n-- Vier verknüpfte Tabellen: artikel, kunden, bestellungen, bestellpositionen\n\nCREATE TABLE artikel (\n    id INTEGER PRIMARY KEY,\n    name TEXT,\n    preis REAL\n);\n\nCREATE TABLE kunden (\n    id INTEGER PRIMARY KEY,\n    name TEXT\n);\n\nCREATE TABLE bestellungen (\n    id INTEGER PRIMARY KEY,\n    kunden_id INTEGER REFERENCES kunden(id),\n    datum TEXT,\n    status TEXT\n);\n\nCREATE TABLE bestellpositionen (\n    bestellung_id INTEGER REFERENCES bestellungen(id),\n    artikel_id INTEGER REFERENCES artikel(id),\n    menge INTEGER,\n    PRIMARY KEY (bestellung_id, artikel_id)\n);\n\nINSERT INTO artikel (id, name, preis) VALUES (1, 'Maus', 25.90);\nINSERT INTO artikel (id, name, preis) VALUES (2, 'Tastatur', 55.00);\nINSERT INTO artikel (id, name, preis) VALUES (3, 'Monitor', 189.00);\nINSERT INTO artikel (id, name, preis) VALUES (4, 'USB-Kabel', 7.99);\n\nINSERT INTO kunden (id, name) VALUES (1, 'Lena');\nINSERT INTO kunden (id, name) VALUES (2, 'Jonas');\n\nINSERT INTO bestellungen (id, kunden_id, datum, status) VALUES (1, 1, '2026-11-03', 'offen');\nINSERT INTO bestellungen (id, kunden_id, datum, status) VALUES (2, 2, '2026-11-05', 'versendet');\n\nINSERT INTO bestellpositionen (bestellung_id, artikel_id, menge) VALUES (1, 2, 1);\nINSERT INTO bestellpositionen (bestellung_id, artikel_id, menge) VALUES (1, 4, 3);\nINSERT INTO bestellpositionen (bestellung_id, artikel_id, menge) VALUES (2, 3, 1);"]]],
            ['id' => 43, 'title' => 'Java: Objektbeziehungen umsetzen - die Schulklasse verwaltet ihre Schueler (1:n)', 'description' => 'Objekte kennen einander: Eine Schulklasse verwaltet viele Schueler (1:n). Lege die Klassen Schueler und Schulklasse an, speichere die Schueler in einem privaten Array und gib die Klassenliste mit einer for-Schleife aus. Danach baust du den Rueckverweis: Jeder Schueler merkt sich seine Schulklasse. Teste mit drei Schuelern am Dateiende.', 'type' => 'code', 'level' => 10, 'todos' => ['Klasse Schueler mit privatem Attribut name und getName() anlegen', 'Klasse Schulklasse mit privatem Array fuer bis zu 30 Schueler anlegen', 'Methode aufnehmen(Schueler neu): Schueler im Array speichern', 'Methode klassenlisteAusgeben() mit for-Schleife schreiben (getName() benutzen)', 'Rueckverweis bauen: jeder Schueler merkt sich seine Schulklasse (klasseSetzen)', 'Am Dateiende drei Schueler aufnehmen und die Liste ausgeben'], 'solution' => "public class Schueler {\n\n    // Attribute\n    private String name;\n    private Schulklasse klasse;\n\n    // Konstruktor\n    public Schueler(String nameStart) {\n        name = nameStart;\n    }\n\n    public String getName() {\n        return name;\n    }\n\n    // Rueckverweis: jeder Schueler kennt seine Klasse\n    public void klasseSetzen(Schulklasse klasseNeu) {\n        klasse = klasseNeu;\n    }\n\n    public void vorstellen() {\n        System.out.println(\"Ich bin \" + getName() + \" aus der Klasse \" + klasse.nameGeben() + \".\");\n    }\n}\n\npublic class Schulklasse {\n\n    // Attribute\n    private String name;\n    private Schueler[] schueler = new Schueler[30];\n    private int anzahl = 0;\n\n    // Konstruktor\n    public Schulklasse(String nameStart) {\n        name = nameStart;\n    }\n\n    public String nameGeben() {\n        return name;\n    }\n\n    // 1:n: die Klasse verwaltet viele Schueler\n    public void aufnehmen(Schueler neu) {\n        if (anzahl < schueler.length) {\n            schueler[anzahl] = neu;\n            anzahl = anzahl + 1;\n        }\n    }\n\n    public void klassenlisteAusgeben() {\n        System.out.println(\"Klasse \" + name + \":\");\n        for (int i = 0; i < anzahl; i++) {\n            System.out.println(\"- \" + schueler[i].getName());\n        }\n    }\n}\n\n// Testanweisungen am Dateiende\nSchulklasse klasse10c = new Schulklasse(\"10c\");\nSchueler lena = new Schueler(\"Lena\");\nSchueler jonas = new Schueler(\"Jonas\");\nSchueler emma = new Schueler(\"Emma\");\nklasse10c.aufnehmen(lena);\nklasse10c.aufnehmen(jonas);\nklasse10c.aufnehmen(emma);\nlena.klasseSetzen(klasse10c);\njonas.klasseSetzen(klasse10c);\nemma.klasseSetzen(klasse10c);\nklasse10c.klassenlisteAusgeben();\nlena.vorstellen();", 'files' => [['name' => 'SchulklasseStarter.java', 'content' => "// Vorlage: Objektbeziehungen 1:n\n// Die Schulklasse verwaltet ihre Schueler - ergaenze beide Klassen.\n\npublic class Schueler {\n\n    // Attribute (privat: name, klasse)\n\n    // Konstruktor mit nameStart\n\n    // Methode getName()\n\n    // Methode klasseSetzen(Schulklasse klasseNeu)\n\n    // Methode vorstellen()\n}\n\npublic class Schulklasse {\n\n    // Attribute (privat: name, Array fuer 30 Schueler, anzahl)\n\n    // Konstruktor mit nameStart\n\n    // Methode nameGeben()\n\n    // Methode aufnehmen(Schueler neu)\n\n    // Methode klassenlisteAusgeben()\n}\n\n// 1) Schulklasse und drei Schueler anlegen\n// 2) aufnehmen() und klasseSetzen() aufrufen\n// 3) klassenlisteAusgeben() und vorstellen() testen"]]],
            ['id' => 44, 'title' => 'Projekt: Testfälle planen und systematisch testen', 'description' => 'Bevor ihr euer Projekt (Datenbank oder Java-Programm) vorstellt, plant ihr Testfälle: eine Tabelle mit Testfall, Eingabe, erwarteter Ausgabe und tatsächlichem Ergebnis. Testet gezielt Grenzfälle wie eine leere Liste oder eine falsche Eingabe und führt ein Fehlerprotokoll mit Korrekturen.', 'type' => 'allgemein', 'level' => 10, 'todos' => ['Testfall-Tabelle anlegen: Nummer, Eingabe, erwartete Ausgabe, Ergebnis', 'Mindestens acht Testfälle planen, darunter drei Grenzfälle', 'Grenzfälle festlegen (leere Menge, falsche Eingabe, Wert 0)', 'Alle Testfälle ausführen und das Ergebnis notieren', 'Gefundene Fehler im Fehlerprotokoll erfassen: Was? Wo? Wann behoben?', 'Korrigierte Stellen erneut testen (Regressionstest)'], 'solution' => "Beispiel-Tabelle (Auszug):\n\nNr | Eingabe                       | erwartet                | Ergebnis\n1  | Klasse anlegen                | Objekt existiert        | ok\n2  | Buchung ohne freies Fahrrad   | Meldung, kein Absturz   | ok\n3  | leere Buchungsliste           | 0 statt Fehler           | ok\n4  | Preis -5 Euro                 | Eingabe abgewiesen      | FEHLER\n\nFehlerprotokoll zu Nr 4: Ursache - negative Preise wurden nicht geprüft. Behoben am 12.11., danach Testfall 4 erneut ausgeführt: ok (Regressionstest).\n\nFaustregel: Ein Testfall prüft genau eine Sache. Erst wenn jeder Testfall ok ist, wird das Projekt vorgestellt."],
            ['id' => 45, 'title' => 'SQL: Bedingungen verknüpfen mit AND, OR und NOT', 'description' => 'Suchanfragen werden erst durch verknüpfte Bedingungen richtig mächtig: Finde alle Artikel unter 20 Euro, die auf Lager sind (AND), alle Kunden aus zwei Städten (OR) oder alle Bestellungen, die noch nicht bezahlt sind (NOT). Nutze die Vorlage shop.sql in der SQL-Werkstatt und schreibe zu jeder Frage eine Abfrage, mit Klammern, wenn nötig.', 'type' => 'sql', 'level' => 10, 'todos' => ['Vorlage shop.sql in der SQL-Werkstatt ausführen', 'Abfrage mit AND: billige Artikel, die auf Lager sind', 'Abfrage mit OR: Kunden aus zwei verschiedenen Städten', 'Abfrage mit NOT bzw. !=: noch nicht bezahlte Bestellungen', 'Eine Abfrage mit Klammern schreiben, in der AND und OR gemischt vorkommen', 'Erklären, warum die Klammer-Abfrage ohne Klammern ein anderes Ergebnis liefert'], 'solution' => "Beispiel-Abfragen:\n\n-- AND: beide Bedingungen muessen gleichzeitig gelten\nSELECT name, preis FROM artikel WHERE preis < 20 AND lager > 0;\n\n-- OR: mindestens eine Bedingung muss gelten\nSELECT name, stadt FROM kunden WHERE stadt = 'Muenchen' OR stadt = 'Dresden';\n\n-- NOT: die Bedingung darf nicht gelten\nSELECT id, datum FROM bestellungen WHERE NOT bezahlt = 1;\n-- gleichwertig: WHERE bezahlt != 1\n\n-- Klammern: AND bindet staerker als OR, darum bekommen Mischungen Klammern\nSELECT name FROM artikel WHERE (kategorie = 'Zubehoer' OR kategorie = 'Werkzeug') AND preis < 50;\n\nOhne Klammern lautet die Abfrage: (kategorie = 'Zubehoer') OR (kategorie = 'Werkzeug' AND preis < 50). Dann taucht auch das teure Multimeter (89 Euro) auf, obwohl es die Preisregel verletzt.", 'files' => [['name' => 'shop.sql', 'content' => "-- Beispieldatenbank: kleiner Online-Shop zum Ueben verknuepfter Bedingungen\n\nCREATE TABLE kunden (\n    id INTEGER PRIMARY KEY,\n    name TEXT,\n    stadt TEXT\n);\n\nCREATE TABLE artikel (\n    id INTEGER PRIMARY KEY,\n    name TEXT,\n    kategorie TEXT,\n    preis REAL,\n    lager INTEGER\n);\n\nCREATE TABLE bestellungen (\n    id INTEGER PRIMARY KEY,\n    kunde_id INTEGER REFERENCES kunden(id),\n    artikel_id INTEGER REFERENCES artikel(id),\n    datum TEXT,\n    bezahlt INTEGER\n);\n\nINSERT INTO kunden VALUES (1, 'Lena', 'Muenchen');\nINSERT INTO kunden VALUES (2, 'Jonas', 'Dresden');\nINSERT INTO kunden VALUES (3, 'Emma', 'Augsburg');\nINSERT INTO kunden VALUES (4, 'Tim', 'Muenchen');\n\nINSERT INTO artikel VALUES (1, 'USB-Kabel', 'Zubehoer', 7.9, 40);\nINSERT INTO artikel VALUES (2, 'Lupe', 'Werkzeug', 12.5, 3);\nINSERT INTO artikel VALUES (3, 'Profi-Multimeter', 'Werkzeug', 89.0, 5);\nINSERT INTO artikel VALUES (4, 'Ladekabel', 'Zubehoer', 15.0, 0);\nINSERT INTO artikel VALUES (5, 'Radiergummi', 'Schreibwaren', 0.8, 200);\n\nINSERT INTO bestellungen VALUES (1, 1, 1, '2026-11-02', 1);\nINSERT INTO bestellungen VALUES (2, 1, 4, '2026-11-03', 0);\nINSERT INTO bestellungen VALUES (3, 2, 3, '2026-11-04', 0);\nINSERT INTO bestellungen VALUES (4, 3, 5, '2026-11-05', 1);"]]],
            ['id' => 46, 'title' => 'Datenanalyse und Gesellschaft: Chancen und Risiken verknüpfter Daten', 'description' => 'Wenn Tabellen verknüpft werden (Kunden, Bestellungen, Produkte), entstehen Muster, die einzelne Daten nicht zeigen: Wer kauft was, wann, wo? Recherchiert an einem Beispiel (Onlineshop, Bibliothek, Social Media oder Krankenakte), welche Chancen solche Auswertungen bieten (bessere Vorschläge, Planung, Betrugserkennung) und welche Risiken entstehen (Profilbildung, fortgepflanzte Fehler, Überwachung). Erstellt eine Gegenüberstellung mit je drei Argumenten und einer begründeten Empfehlung.', 'type' => 'allgemein', 'level' => 10, 'todos' => ['Beispielszenario wählen: Onlineshop, Bibliothek, Social Media oder Krankenakte', 'Drei Chancen verknüpfter Daten sammeln, je mit Beispiel', 'Drei Risiken verknüpfter Daten sammeln, je mit Beispiel', 'Mindestens ein Risiko an einem konkreten Fall zeigen: Was wäre schiefgelaufen?', 'Empfehlung formulieren: Wann ist eine Auswertung vertretbar, wann nicht?', 'Ergebnis als Gegenüberstellung (Tabelle) abgeben'], 'solution' => "Gegenueberstellung (Beispiel Onlineshop):\n\nChancen:\n1. Bessere Angebote: Verknuepfung von Bestellungen und Produkten zeigt, was Kundinnen und Kunden wirklich brauchen.\n2. Planung: Der Laden bestellt nach, bevor etwas ausverkauft ist (Lagerbestand und Verkaeufe verknuepft).\n3. Betrugserkennung: Ungewoehnliche Kombinationen (neues Konto, viele teure Bestellungen kurz hintereinander) fallen auf.\n\nRisiken:\n1. Profilbildung: Aus vielen kleinen Daten entsteht ein detailliertes Bild einer Person, das sie nie selbst freigegeben hat.\n2. Fehler pflanzen sich fort: Eine falsche Adresse in einer Tabelle verfaelscht jede Auswertung, die sie verknuepft.\n3. Ueberwachung: Ohne klare Regeln entsteht Transparenz nur fuer die Auswertenden, nicht fuer die Betroffenen.\n\nEmpfehlung (Beispiel): Auswertungen sind vertretbar, wenn sie anonymisiert sind, der Zweck konkret benannt ist und Betroffene Widerspruch einlegen koennen. Eine Auswertung nur zum Weiterverkauf von Profilen ist es nicht."],
            // Oberstufe
            ['id' => 19, 'title' => 'Normalisierung bis zur dritten Normalform', 'description' => 'Gegeben ist eine unstrukturierte Schueler-Tabelle mit Redundanzen. Überführe sie schrittweise in die 1., 2. und 3. Normalform und begründe jeden Schritt mit der verletzten Regel.', 'type' => 'sql', 'level' => 11],
            ['id' => 20, 'title' => 'Laufzeiten vergleichen (O-Notation)', 'description' => 'Ordne die folgenden Algorithmen ihrer Komplexitätsklasse zu: lineare Suche, binäre Suche, Bubblesort, ein verschachtelter Durchlauf. Begründe je eine Zeile und skizziere die Laufzeit als Funktion der Eingabegröße.', 'type' => 'allgemein', 'level' => 11],
